  const sorted=useMemo(()=>sortDocumentRows(filtered,sort),[filtered,sort]);
  const pages=Math.max(1,Math.ceil(sorted.length/pageSize)),current=Math.min(page,pages),visible=sorted.slice((current-1)*pageSize,current*pageSize),shown=displayedColumns(columnSettings);
  const normal=state==='normal',active=normal?filtered.find(row=>row.id===activeId)??filtered[0]:null;
  const output=outputRows(filtered,selected);
  const resetSelection=()=>{setSelected([]);setPage(1);};
  const switchState=value=>{clearTimeout(timer.current);setState(value);resetSelection();};
  const refresh=()=>{resetSelection();setState('loading');clearTimeout(timer.current);timer.current=setTimeout(()=>{setState('normal');notify('Đã tải lại mẫu trong bộ nhớ, giữ bộ lọc hiện tại.');},650);};
  const apply=()=>{if(!validRange(draftRange)){setFilterError('Khoảng ngày chưa hợp lệ: từ ngày phải trước hoặc bằng đến ngày.');return;}setFilterError('');setRange({...draftRange});resetSelection();};
  const toggle=id=>setSelected(previous=>previous.includes(id)?previous.filter(key=>key!==id):[...previous,id]);
