  const [step,setStep]=useState(0),[file,setFile]=useState(null),[sheets,setSheets]=useState([]),[sheet,setSheet]=useState('0'),[header,setHeader]=useState('1'),[data,setData]=useState(null),[mapping,setMapping]=useState({}),[errors,setErrors]=useState({}),[error,setError]=useState(''),[busy,setBusy]=useState(''),[plan,setPlan]=useState(null),[result,setResult]=useState(null),[drag,setDrag]=useState(false);
